/*
 * TURN MESSAGE EMAILS ON OR OFF FOR THE SIGNED-IN ACCOUNT (DBU-07), from the Messages page.
 * The only thing that turns them back on (the unsubscribe link only ever turns them off).
 * Turning off keeps the first stamp, so "when did she ask" stays the moment she first asked.
 * Sign-in emails are the backend's own and are never affected.
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const state = String(Inputs.state || '');
    if (state !== 'on' && state !== 'off') { Outputs.why = 'Choose on or off.'; Outputs.refuse(); return; }
    const users = await Noodl.Records.query('_User', { objectId: { equalTo: me } }, { limit: 2, plain: true });
    if (users.length !== 1) throw new Error('no account');
    const stamp = state === 'on' ? null : users[0].emailOptOutAt || new Date().toISOString();
    await Noodl.Records.save(me, { emailOptOutAt: stamp }, { className: '_User' });
    Outputs.emailOn = state === 'on';
    Outputs.done();
  } catch (e) {
    console.error('[dbu:setEmailPreference]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
